const clamp=(v,a,b)=>Math.max(a,Math.min(b,Number(v)||0));const normRot=v=>((Number(v||0)+180)%360+360)%360-180;
export function resizeFromHandle(rect,handle,delta,{aspectLocked=false,minSize=2}={}){let {x,y,width,height}=rect;const dx=Number(delta?.x)||0,dy=Number(delta?.y)||0,ratio=width/height||1;if(handle.includes('e'))width+=dx;if(handle.includes('s'))height+=dy;if(handle.includes('w')){x+=dx;width-=dx;}if(handle.includes('n')){y+=dy;height-=dy;}width=Math.max(minSize,width);height=Math.max(minSize,height);if(aspectLocked){if(Math.abs(dx)>=Math.abs(dy)){const nh=width/ratio;if(handle.includes('n'))y+=height-nh;height=nh;}else{const nw=height*ratio;if(handle.includes('w'))x+=width-nw;width=nw;}}return{x,y,width,height};}
export function rotateFromPointer(center,pointer,start={}){const angle=Math.atan2(pointer.y-center.y,pointer.x-center.x)*180/Math.PI;const base=Number(start.startAngleDeg)||0,rot=Number(start.startRotationDeg)||0;return normRot(rot+angle-base);}
export function snapRect(rect,targets,{thresholdPx=8,viewportScale=1}={}){const r={...rect},guides=[],threshold=Math.max(.1,thresholdPx/Math.max(.01,viewportScale));const cx=()=>r.x+r.width/2,cy=()=>r.y+r.height/2;for(const t of targets||[]){if(t.axis==='x'){const candidates=t.kind==='edge'?[['left',r.x],['right',r.x+r.width]]:[['center',cx()]];let best=candidates.map(([kind,v])=>({kind,v,d:Math.abs(v-t.value)})).sort((a,b)=>a.d-b.d)[0];if(best.d<=threshold){if(best.kind==='left')r.x=t.value;else if(best.kind==='center')r.x=t.value-r.width/2;else r.x=t.value-r.width;guides.push(t);}}else if(t.axis==='y'){const candidates=t.kind==='edge'?[['top',r.y],['bottom',r.y+r.height]]:[['center',cy()]];let best=candidates.map(([kind,v])=>({kind,v,d:Math.abs(v-t.value)})).sort((a,b)=>a.d-b.d)[0];if(best.d<=threshold){if(best.kind==='top')r.y=t.value;else if(best.kind==='center')r.y=t.value-r.height/2;else r.y=t.value-r.height;guides.push(t);}}}return{rect:r,guides};}
export function flipTransform(transform={},axis){const t={...transform};if(axis==='x')t.flipX=!t.flipX;else if(axis==='y')t.flipY=!t.flipY;return t;}
export function normalizeCrop(crop={}){let left=clamp(crop.left,0,.95),top=clamp(crop.top,0,.95),right=clamp(crop.right,0,.95),bottom=clamp(crop.bottom,0,.95);if(left+right>.95)right=.95-left;if(top+bottom>.95)bottom=.95-top;return{left,top,right,bottom};}
export function applyCropDrag(crop,handle,deltaNormalized={}){const c=normalizeCrop(crop),dx=Number(deltaNormalized.x)||0,dy=Number(deltaNormalized.y)||0;if(handle.includes('left'))c.left+=dx;if(handle.includes('right'))c.right-=dx;if(handle.includes('top'))c.top+=dy;if(handle.includes('bottom'))c.bottom-=dy;return normalizeCrop(c);}
